{"command":"cat <<EOF > /prediction.json
{
    "vllm/v1/sample/rejection_sampler.py": {
        "rejection_greedy_sample_kernel": "@triton.jit(do_not_specialize=[\"max_spec_len\"])\ndef rejection_greedy_sample_kernel(\n    output_token_ids_ptr,  # [batch_size, max_spec_len + 1]\n    cu_num_draft_tokens_ptr,  # [batch_size]\n    draft_token_ids_ptr,  # [num_tokens]\n    target_argmax_ptr,  # [num_tokens]\n    bonus_token_ids_ptr,  # [batch_size]\n    is_greedy_ptr,  # [batch_size] or None\n    max_spec_len,\n):\n    req_idx = tl.program_id(0)\n\n    if is_greedy_ptr:\n        is_greedy = tl.load(is_greedy_ptr + req_idx)\n        if not is_greedy:\n            return\n\n    start_idx = tl.load(cu_num_draft_tokens_ptr + req_idx - 1) if req_idx > 0 else 0\n    end_idx = tl.load(cu_num_draft_tokens_ptr + req_idx)\n    num_draft_tokens = end_idx - start_idx\n\n    offsets = tl.arange(0, 64)\n    mask = offsets < num_draft_tokens\n\n    draft_tokens = tl.load(draft_token_ids_ptr + start_idx + offsets,\n                           mask=mask,\n                           other=-1)\n    target_tokens = tl.load(target_argmax_ptr + start_idx + offsets,\n                            mask=mask,\n                            other=-2)\n\n    rejected = (draft_tokens != target_tokens) & mask\n    first_rejection_idx = tl.min(tl.where(rejected, offsets, 64), axis=0)\n\n    last_idx = tl.minimum(first_rejection_idx, num_draft_tokens)\n\n    if last_idx < num_draft_tokens:\n        last_token = tl.load(target_argmax_ptr + start_idx + last_idx)\n    else:\n        last_token = tl.load(bonus_token_ids_ptr + req_idx)\n\n    accepted_draft_tokens = tl.load(draft_token_ids_ptr + start_idx + offsets,\n                                    mask=offsets < last_idx,\n                                    other=0)\n    val = tl.where(offsets < last_idx, accepted_draft_tokens, last_token)\n\n    tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + offsets,\n             val,\n             mask=offsets <= last_idx)",
        "rejection_random_sample_kernel": "@triton.jit(do_not_specialize=[\"max_spec_len\"])\ndef rejection_random_sample_kernel(\n    output_token_ids_ptr,  # [batch_size, max_spec_len + 1]\n    cu_num_draft_tokens_ptr,  # [batch_size]\n    draft_token_ids_ptr,  # [num_tokens]\n    draft_probs_ptr,  # [num_tokens, vocab_size] or None\n    target_probs_ptr,  # [num_tokens, vocab_size]\n    bonus_token_ids_ptr,  # [batch_size]\n    recovered_token_ids_ptr,  # [num_tokens]\n    uniform_probs_ptr,  # [num_tokens]\n    is_greedy_ptr,  # [batch_size]\n    max_spec_len,\n    vocab_size,\n    IS_NGRAM: tl.constexpr,\n):\n    req_idx = tl.program_id(0)\n\n    # is_greedy_ptr is not None here.\n    is_greedy = tl.load(is_greedy_ptr + req_idx)\n    if is_greedy:\n        return\n\n    start_idx = tl.load(cu_num_draft_tokens_ptr + req_idx - 1) if req_idx > 0 else 0\n    end_idx = tl.load(cu_num_draft_tokens_ptr + req_idx)\n    num_draft_tokens = end_idx - start_idx\n\n    offsets = tl.arange(0, 64)\n    mask = offsets < num_draft_tokens\n\n    token_indices = start_idx + offsets\n    draft_token_ids = tl.load(draft_token_ids_ptr + token_indices,\n                              mask=mask,\n                              other=0)\n\n    if IS_NGRAM:\n        draft_probs = 1.0\n    else:\n        draft_probs = tl.load(draft_probs_ptr + token_indices * vocab_size +\n                              draft_token_ids,\n                              mask=mask,\n                              other=1.0)\n\n    target_probs = tl.load(target_probs_ptr + token_indices * vocab_size +\n                           draft_token_ids,\n                           mask=mask,\n                           other=0.0)\n    uniform_probs = tl.load(uniform_probs_ptr + token_indices,\n                            mask=mask,\n                            other=1.0)\n\n    # Accept if uniform_probs * draft_probs < target_probs\n    rejected = (uniform_probs * draft_probs >= target_probs) & mask\n    first_rejection_idx = tl.min(tl.where(rejected, offsets, 64), axis=0)\n\n    last_idx = tl.minimum(first_rejection_idx, num_draft_tokens)\n\n    if last_idx < num_draft_tokens:\n        last_token = tl.load(recovered_token_ids_ptr + start_idx + last_idx)\n    else:\n        last_token = tl.load(bonus_token_ids_ptr + req_idx)\n\n    accepted_draft_tokens = tl.load(draft_token_ids_ptr + start_idx + offsets,\n                                    mask=offsets < last_idx,\n                                    other=0)\n    val = tl.where(offsets < last_idx, accepted_draft_tokens, last_token)\n\n    tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + offsets,\n             val,\n             mask=offsets <= last_idx)"
    }
}
EOF
"}

